3	(function setupBookingPage() {
4	  const NO_REPLY = 'Could not reach the server.';
5	  const FALLBACK_ERROR = 'Request failed.';
6	  const SUCCESS_STATUS = { GET: 200, POST: 201, DELETE: 204 };
7	
8	  const form = document.getElementById('booking-form');
9	  const roomSelect = document.getElementById('room');
10	  const titleInput = document.getElementById('title');
11	  const dateInput = document.getElementById('date');
12	  const startInput = document.getElementById('start');
13	  const endInput = document.getElementById('end');
14	  const bookButton = document.getElementById('book');
15	  const filterDate = document.getElementById('filter-date');
16	  const showAllButton = document.getElementById('show-all');
17	  const bookingList = document.getElementById('booking-list');
18	  const errorBox = document.getElementById('error');
19	
20	  let listGeneration = 0;
21	
22	  // Resolves to { ok, status, body } when a reply arrived, or null when there was none.
23	  // A non-204 reply whose body is not JSON counts as no reply.
24	  async function request(method, url, payload) {
25	    const options = payload === undefined
26	      ? { method }
27	      : { method, headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) };
28	    try {
29	      const reply = await fetch(url, options);
30	      const body = reply.status === 204 ? undefined : await reply.json();
31	      return { ok: reply.status === SUCCESS_STATUS[method], status: reply.status, body };
32	    } catch {
33	      // Network failure or unreadable body: the caller shows the no-reply message.
34	      return null;
35	    }
36	  }
37	
38	  function errorMessage(body) {
39	    const isObject = body !== null && typeof body === 'object' && !Array.isArray(body);
40	    return isObject && typeof body.error === 'string' ? body.error : FALLBACK_ERROR;
41	  }
42	
43	  // The array under `key` in a success body, or null when the body has an unexpected shape.
44	  function listField(body, key) {
45	    const isObject = body !== null && typeof body === 'object';
46	    return isObject && Array.isArray(body[key]) ? body[key] : null;
47	  }
48	
49	  function showError(text) {
50	    errorBox.textContent = text;
51	  }
52	
53	  function showOutcomeError(result) {
54	    showError(result === null ? NO_REPLY : errorMessage(result.body));
55	  }
56	
57	  async function loadRooms() {
58	    const result = await request('GET', '/api/rooms');
59	    if (result === null || !result.ok) {
60	      showOutcomeError(result);
61	      return;
62	    }
63	    const rooms = listField(result.body, 'rooms');
64	    if (rooms === null) {
65	      showError(FALLBACK_ERROR);
66	      return;
67	    }
68	    const options = rooms.map((name) => {
69	      const option = document.createElement('option');
70	      option.value = name;
71	      option.textContent = name;
72	      return option;
73	    });
74	    roomSelect.replaceChildren(...options);
75	  }
76	
77	  function bookingItem(booking) {
78	    const item = document.createElement('li');
79	    const cancel = document.createElement('button');
80	    cancel.type = 'button';
81	    cancel.textContent = 'Cancel';
82	    cancel.addEventListener('click', () => cancelBooking(booking.id, cancel));
83	    const text = `${booking.date} ${booking.start}-${booking.end} ${booking.room}: ${booking.title}`;
84	    item.append(text, cancel);
85	    return item;
86	  }
87	
88	  function emptyItem() {
89	    const item = document.createElement('li');
90	    item.append('No bookings.');
91	    return item;
92	  }
93	
94	  async function loadList() {
95	    listGeneration += 1;
96	    const generation = listGeneration;
97	    const filter = filterDate.value;
98	    const url = filter === '' ? '/api/bookings' : `/api/bookings?date=${filter}`;
99	    const result = await request('GET', url);
100	    if (generation !== listGeneration) {
101	      return;
102	    }
103	    if (result === null || !result.ok) {
104	      showOutcomeError(result);
105	      return;
106	    }
107	    const bookings = listField(result.body, 'bookings');
108	    if (bookings === null) {
109	      showError(FALLBACK_ERROR);
110	      return;
111	    }
112	    const items = bookings.length === 0 ? [emptyItem()] : bookings.map(bookingItem);
113	    bookingList.replaceChildren(...items);
114	  }
115	
116	  async function cancelBooking(id, button) {
117	    button.disabled = true;
118	    const result = await request('DELETE', `/api/bookings/${id}`);
119	    button.disabled = false;
120	    if (result === null) {
121	      showError(NO_REPLY);
122	      return;
123	    }
124	    showError(result.ok ? '' : errorMessage(result.body));
125	    loadList();
126	  }
127	
128	  async function submitBooking(event) {
129	    event.preventDefault();
130	    if (bookButton.disabled) {
131	      return;
132	    }
133	    bookButton.disabled = true;
134	    const payload = {
135	      room: roomSelect.value,
136	      title: titleInput.value,
137	      date: dateInput.value,
138	      start: startInput.value,
139	      end: endInput.value,
140	    };
141	    const result = await request('POST', '/api/bookings', payload);
142	    bookButton.disabled = false;
143	    if (result === null || !result.ok) {
144	      showOutcomeError(result);
145	      return;
146	    }
147	    titleInput.value = '';
148	    showError('');
149	    loadList();
150	  }
151	
152	  function showAll() {
153	    filterDate.value = '';
154	    loadList();
155	  }
156	
157	  form.addEventListener('submit', submitBooking);
158	  filterDate.addEventListener('change', () => loadList());
159	  showAllButton.addEventListener('click', showAll);
160	
161	  loadRooms();
162	  loadList();
163	})();
