11	export class FakeElement {
12	  constructor(tagName, id = '') {
13	    this.tagName = tagName;
14	    this.id = id;
15	    this.children = [];
16	    this.value = '';
17	    this.type = '';
18	    this.disabled = false;
19	    this.listeners = new Map();
20	  }
21	
22	  get textContent() {
23	    return this.children.map((c) => c.textContent).join('');
24	  }
25	
26	  set textContent(s) {
27	    if (this.onTextSet) this.onTextSet(s);
28	    this.children = s === '' ? [] : [toNode(String(s))];
29	  }
30	
31	  append(...nodes) {
32	    this.children = [...this.children, ...nodes.map(toNode)];
33	  }
34	
35	  replaceChildren(...nodes) {
36	    this.children = nodes.map(toNode);
37	  }
38	
39	  addEventListener(type, fn) {
40	    this.listeners.set(type, [...(this.listeners.get(type) ?? []), fn]);
41	  }
42	
43	  dispatch(type) {
44	    const event = { preventDefault() { this.defaultPrevented = true; }, defaultPrevented: false };
45	    for (const fn of this.listeners.get(type) ?? []) fn(event);
46	    return event;
47	  }
48	}
