50	export function deferred() {
51	  let resolve;
52	  let reject;
53	  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
54	  return { promise, resolve, reject };
55	}
56	
57	export function makeReply(status, body, { badJson = false } = {}) {
58	  const reply = {
59	    status,
60	    jsonCalls: 0,
61	    json() {
62	      reply.jsonCalls += 1;
63	      return badJson ? Promise.reject(new SyntaxError('bad json')) : Promise.resolve(body);
64	    },
65	  };
66	  return reply;
67	}
68	
69	export async function flush() {
70	  for (let i = 0; i < 5; i += 1) await new Promise((r) => setImmediate(r));
71	}
72	
73	export function loadPage(appPath) {
74	  const els = Object.fromEntries(IDS.map((id) => [id, new FakeElement('x', id)]));
75	  const calls = [];
76	  const document = {
77	    getElementById: (id) => els[id],
78	    createElement: (tag) => new FakeElement(tag),
79	  };
80	  const fetch = (url, options) => {
81	    const d = deferred();
82	    calls.push({ url, options, bookDisabled: els.book.disabled, reply: (r) => d.resolve(r), fail: (e) => d.reject(e ?? new TypeError('down')) });
83	    return d.promise;
84	  };
85	  const context = vm.createContext({ document, fetch });
86	  vm.runInContext(fs.readFileSync(appPath, 'utf8'), context, { filename: 'app.js' });
87	  return { els, calls };
88	}
